{
  "packet_id": "H6-T03-2",
  "claim_id": "C017",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017.component",
    "value": "If a case lacks adequate support and its identified sources are inaccessible, active reconstruction is to stop and the case is to be reported as unresolved with a named follow-up owner and next step.",
    "scope": "The source-inaccessibility stopping alternative. The mapping does not specify how much source inaccessibility triggers this condition.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P013 explicitly supplies the stopping condition, unresolved disposition, and follow-up requirements."
    }
  },
  "signal_basis": {
    "component_id": "C017.signal_basis",
    "value": "The case's applicability or relevant sequence lacks adequate support, and identified sources are inaccessible.",
    "scope": "A condition for stopping active reconstruction and retaining an unresolved case; the extent of source inaccessibility required is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P013 states inadequate support and source inaccessibility as the relevant conditions for this procedural alternative."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This is a supported procedural stopping rule; no unresolved empirical relation is needed to license its bounded disposition."
    }
  },
  "rationale": "Given the stated condition, stopping active reconstruction while explicitly retaining unresolved status and assigning follow-up is licensed by the mapping's procedural rule. It makes no claim that approval was absent or that further evidence cannot exist.",
  "uncertainty": "The mapping leaves the required extent of source inaccessibility unspecified. This limits operational precision but does not defeat the warrant when the stated stopping condition is assumed satisfied.",
  "anomalies": []
}
